-- Migración 0008. Registra qué lotes se embarcan en cada expedición y en qué momento.
-- Sirve para cualquier tipo de lote: tarima, caja, bulto o tambo suelto.
-- El producto sigue en el lote final. Esta tabla solo relaciona ese lote con la expedición.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

CREATE TABLE "EXPEDICIONES_LOTES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_EXPEDICION" integer NOT NULL,
  "ID_LOTE" integer NOT NULL UNIQUE,
  "EMBARCADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "EXPEDICIONES_LOTES_ID_EXPEDICION_FK"
    FOREIGN KEY ("ID_EXPEDICION") REFERENCES "EXPEDICIONES" ("ID"),
  CONSTRAINT "EXPEDICIONES_LOTES_ID_LOTE_FK"
    FOREIGN KEY ("ID_LOTE") REFERENCES "LOTES" ("ID")
);

CREATE INDEX "EXPEDICIONES_LOTES_ID_EXPEDICION_IDX"
  ON "EXPEDICIONES_LOTES" ("ID_EXPEDICION");

CREATE OR REPLACE FUNCTION expediciones_lotes_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  cierre timestamptz;
  creada timestamptz;
  cierre_anterior timestamptz;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT "FECHA_CIERRE" INTO cierre
    FROM "EXPEDICIONES"
    WHERE "ID" = OLD."ID_EXPEDICION";

    IF cierre IS NOT NULL THEN
      RAISE EXCEPTION 'la expedicion cerrada conserva sus lotes' USING ERRCODE = '23514';
    END IF;

    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT "FECHA_CIERRE" INTO cierre_anterior
    FROM "EXPEDICIONES"
    WHERE "ID" = OLD."ID_EXPEDICION";

    IF cierre_anterior IS NOT NULL THEN
      RAISE EXCEPTION 'la expedicion cerrada conserva sus lotes' USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT "FECHA_CIERRE", "CREADO_EN" INTO cierre, creada
  FROM "EXPEDICIONES"
  WHERE "ID" = NEW."ID_EXPEDICION";

  IF creada IS NULL THEN
    RAISE EXCEPTION 'expedicion inexistente' USING ERRCODE = '23503';
  END IF;

  IF cierre IS NOT NULL THEN
    RAISE EXCEPTION 'no se embarcan lotes en una expedicion cerrada' USING ERRCODE = '23514';
  END IF;

  IF NEW."EMBARCADO_EN" < creada THEN
    RAISE EXCEPTION 'el embarque no puede ser anterior a la expedicion' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "EXPEDICIONES_LOTES_TRG"
  BEFORE INSERT OR UPDATE OR DELETE ON "EXPEDICIONES_LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION expediciones_lotes_validar();

ALTER FUNCTION expediciones_lotes_validar() OWNER TO packing;
